CREATE TABLE s.ctab_ph2 (id int NOT NULL) PARTITION BY HASH (id);
CREATE TABLE s.ctab_ph2_0 PARTITION OF s.ctab_ph2 FOR VALUES WITH (MODULUS 8, REMAINDER 0);
CREATE TABLE s.ctab_ph2_1 PARTITION OF s.ctab_ph2 FOR VALUES WITH (MODULUS 8, REMAINDER 1)

CREATE TABLE s.ctab_def1 (id int, region text) PARTITION BY LIST (region);
CREATE TABLE s.ctab_def1_us PARTITION OF s.ctab_def1 FOR VALUES IN ('US');
CREATE TABLE s.ctab_def1_other PARTITION OF s.ctab_def1 DEFAULT

CREATE TABLE s.ctab_def2 (id int, d date NOT NULL, PRIMARY KEY (id, d)) PARTITION BY RANGE (d);
CREATE TABLE s.ctab_def2_2024 PARTITION OF s.ctab_def2 FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
CREATE TABLE s.ctab_def2_other PARTITION OF s.ctab_def2 DEFAULT

CREATE TABLE s.ctab_partof_inh (id int, d date NOT NULL) PARTITION BY RANGE (d);
CREATE TABLE s.ctab_partof_inh_p PARTITION OF s.ctab_partof_inh FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
CREATE TABLE s.ctab_partof_child () INHERITS (s.ctab_partof_inh_p)

CREATE TABLE s.ctab_hash3 (id int NOT NULL) PARTITION BY HASH (id);
CREATE TABLE s.ctab_hash3_0 PARTITION OF s.ctab_hash3 FOR VALUES WITH (MODULUS 3, REMAINDER 0);
CREATE TABLE s.ctab_hash3_1 PARTITION OF s.ctab_hash3 FOR VALUES WITH (MODULUS 3, REMAINDER 1);
CREATE TABLE s.ctab_hash3_2 PARTITION OF s.ctab_hash3 FOR VALUES WITH (MODULUS 3, REMAINDER 2)

CREATE TABLE s.ctab_partcol4 (id int, d date NOT NULL, PRIMARY KEY (id, d)) PARTITION BY RANGE (d);
CREATE TABLE s.ctab_partcol4_p PARTITION OF s.ctab_partcol4 FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
SELECT tableoid FROM s.ctab_partcol4_p LIMIT 1

CREATE TABLE s.ctab_part_and_def (id int) PARTITION BY LIST (id);
CREATE TABLE s.ctab_pad_p1 PARTITION OF s.ctab_part_and_def FOR VALUES IN (1);
CREATE TABLE s.ctab_pad_def PARTITION OF s.ctab_part_and_def DEFAULT;
CREATE TABLE s.ctab_pad_def2 PARTITION OF s.ctab_part_and_def DEFAULT

CREATE TABLE s.ctab_rng_overlap (id int, d date NOT NULL, PRIMARY KEY (id, d)) PARTITION BY RANGE (d);
CREATE TABLE s.ctab_rng_overlap_p1 PARTITION OF s.ctab_rng_overlap FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
CREATE TABLE s.ctab_rng_overlap_p2 PARTITION OF s.ctab_rng_overlap FOR VALUES FROM ('2024-06-01') TO ('2025-06-01')

CREATE TABLE s.ctab_list_dup (id int, region text) PARTITION BY LIST (region);
CREATE TABLE s.ctab_list_dup_p1 PARTITION OF s.ctab_list_dup FOR VALUES IN ('US', 'CA');
CREATE TABLE s.ctab_list_dup_p2 PARTITION OF s.ctab_list_dup FOR VALUES IN ('CA', 'MX')

CREATE TABLE s.ctab_hash_dup (id int NOT NULL) PARTITION BY HASH (id);
CREATE TABLE s.ctab_hash_dup_p1 PARTITION OF s.ctab_hash_dup FOR VALUES WITH (MODULUS 4, REMAINDER 0);
CREATE TABLE s.ctab_hash_dup_p2 PARTITION OF s.ctab_hash_dup FOR VALUES WITH (MODULUS 4, REMAINDER 0)

CREATE TABLE s.ctab_part_hash_with_ts (id int NOT NULL) PARTITION BY HASH (id);
CREATE TABLE s.ctab_part_hw_0 PARTITION OF s.ctab_part_hash_with_ts FOR VALUES WITH (MODULUS 2, REMAINDER 0) TABLESPACE pg_default;
CREATE TABLE s.ctab_part_hw_1 PARTITION OF s.ctab_part_hash_with_ts FOR VALUES WITH (MODULUS 2, REMAINDER 1) TABLESPACE pg_default

CREATE TABLE s.ctab_rng_adj (id int, score int) PARTITION BY RANGE (score);
CREATE TABLE s.ctab_rng_adj_p1 PARTITION OF s.ctab_rng_adj FOR VALUES FROM (MINVALUE) TO (50);
CREATE TABLE s.ctab_rng_adj_p2 PARTITION OF s.ctab_rng_adj FOR VALUES FROM (50) TO (MAXVALUE)

CREATE TABLE s.ctab_rng_ts2 (id int, ts timestamp) PARTITION BY RANGE (ts);
CREATE TABLE s.ctab_rng_ts2_q1 PARTITION OF s.ctab_rng_ts2 FOR VALUES FROM ('2024-01-01 00:00:00') TO ('2024-04-01 00:00:00');
CREATE TABLE s.ctab_rng_ts2_q2 PARTITION OF s.ctab_rng_ts2 FOR VALUES FROM ('2024-04-01 00:00:00') TO ('2024-07-01 00:00:00')

CREATE TABLE s.ctab_list_default_overlap (id int, region text) PARTITION BY LIST (region);
CREATE TABLE s.ctab_ldo_def PARTITION OF s.ctab_list_default_overlap DEFAULT;
CREATE TABLE s.ctab_ldo_us PARTITION OF s.ctab_list_default_overlap FOR VALUES IN ('US')
